const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; addSql: string; delSql: string | null }> = {
  eprintln_baseline: { kind: "set", addSql: `INSERT OR IGNORE INTO "eprintln_baseline" ("path", "allowed") VALUES (?, ?)`, delSql: `DELETE FROM "eprintln_baseline" WHERE "path" = ? AND "allowed" = ?` },
  eprintln_hit: { kind: "set", addSql: `INSERT OR IGNORE INTO "eprintln_hit" ("path", "line_no") VALUES (?, ?)`, delSql: `DELETE FROM "eprintln_hit" WHERE "path" = ? AND "line_no" = ?` },
  waiver_block_comment: { kind: "set", addSql: `INSERT OR IGNORE INTO "waiver_block_comment" ("path", "waiver_line") VALUES (?, ?)`, delSql: `DELETE FROM "waiver_block_comment" WHERE "path" = ? AND "waiver_line" = ?` },
  waiver_trailing_comment: { kind: "set", addSql: `INSERT OR IGNORE INTO "waiver_trailing_comment" ("path", "waiver_line") VALUES (?, ?)`, delSql: `DELETE FROM "waiver_trailing_comment" WHERE "path" = ? AND "waiver_line" = ?` },
};

function arrivalStatement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`new_file_no_exceeded_diag: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`new_file_no_exceeded_diag: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.delSql === null) {
      throw new Error(`new_file_no_exceeded_diag: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.delSql, args: bindArgs(arrival.row) };
  }
  return { sql: template.addSql, args: bindArgs(arrival.row) };
}

function applyArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrivalStatement);
  return seam.runner.batch(seam.db, statements);
}

