function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "eprintln_waiver_line";
INSERT OR IGNORE INTO "eprintln_waiver_line" ("path", "waiver_line") SELECT b0."path", b0."waiver_line" FROM "waiver_block_comment" b0;
INSERT OR IGNORE INTO "eprintln_waiver_line" ("path", "waiver_line") SELECT b0."path", b0."waiver_line" FROM "waiver_trailing_comment" b0;
DELETE FROM "eprintln_waived";
INSERT OR IGNORE INTO "eprintln_waived" ("path", "line_no") SELECT b0."path", b1."line_no" FROM "eprintln_waiver_line" b0, "eprintln_hit" b1 WHERE b1."path" = b0."path" AND (b0."waiver_line" >= (b1."line_no" - 1)) AND (b0."waiver_line" <= b1."line_no");
DELETE FROM "eprintln_counted";
INSERT OR IGNORE INTO "eprintln_counted" ("path", "line_no") SELECT b0."path", b0."line_no" FROM "eprintln_hit" b0 WHERE NOT EXISTS (SELECT 1 FROM "eprintln_waived" n0 WHERE n0."path" = b0."path" AND n0."line_no" = b0."line_no");
DELETE FROM "eprintln_count";
INSERT OR IGNORE INTO "eprintln_count" ("path", "hits") SELECT b0."path", count(*) FROM "eprintln_counted" b0 GROUP BY b0."path" HAVING count(*) > 0;
DELETE FROM "diag";
INSERT OR IGNORE INTO "diag" ("path", "line_no", "col3", "col4", "col5", "col6", "col7") SELECT b0."path", 1, 'warning', 'eprintln-exceeded', (b0."hits" || ' counted eprintln! hits; the grandfathered baseline allows ' || b1."allowed" || '. Convert to tracing, or waive the line with @eprintln-ok: <reason>'), 'none', 'none' FROM "eprintln_count" b0, "eprintln_baseline" b1 WHERE b1."path" = b0."path" AND (b0."hits" > b1."allowed");
INSERT OR IGNORE INTO "diag" ("path", "line_no", "col3", "col4", "col5", "col6", "col7") SELECT b0."path", b0."line_no", 'warning', 'eprintln-new-file', 'new eprintln! outside the grandfathered baseline; convert to tracing, or waive with @eprintln-ok: <reason>', 'none', 'none' FROM "eprintln_counted" b0 WHERE NOT EXISTS (SELECT 1 FROM "eprintln_baseline" n0 WHERE n0."path" = b0."path")`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const diag = multisetDiff(before.diag, after.diag);
  const eprintln_baseline = multisetDiff(before.eprintln_baseline, after.eprintln_baseline);
  const eprintln_count = multisetDiff(before.eprintln_count, after.eprintln_count);
  const eprintln_counted = multisetDiff(before.eprintln_counted, after.eprintln_counted);
  const eprintln_hit = multisetDiff(before.eprintln_hit, after.eprintln_hit);
  const eprintln_waived = multisetDiff(before.eprintln_waived, after.eprintln_waived);
  const eprintln_waiver_line = multisetDiff(before.eprintln_waiver_line, after.eprintln_waiver_line);
  const waiver_block_comment = multisetDiff(before.waiver_block_comment, after.waiver_block_comment);
  const waiver_trailing_comment = multisetDiff(before.waiver_trailing_comment, after.waiver_trailing_comment);
  return {
    rels: [
      { rel: "diag", add: diag.add, del: diag.del },
      { rel: "eprintln_baseline", add: eprintln_baseline.add, del: eprintln_baseline.del },
      { rel: "eprintln_count", add: eprintln_count.add, del: eprintln_count.del },
      { rel: "eprintln_counted", add: eprintln_counted.add, del: eprintln_counted.del },
      { rel: "eprintln_hit", add: eprintln_hit.add, del: eprintln_hit.del },
      { rel: "eprintln_waived", add: eprintln_waived.add, del: eprintln_waived.del },
      { rel: "eprintln_waiver_line", add: eprintln_waiver_line.add, del: eprintln_waiver_line.del },
      { rel: "waiver_block_comment", add: waiver_block_comment.add, del: waiver_block_comment.del },
      { rel: "waiver_trailing_comment", add: waiver_trailing_comment.add, del: waiver_trailing_comment.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // new_file_no_exceeded_diag: no edge rules -- absorb arrivals, recompute levels, diff.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = true;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepareTick(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => of(undefined)),
    concatMap(() => of(undefined)),
    concatMap(() => IncrementalRuntime.recomputeLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promoteFrontiers(seam, INCREMENTAL_RELATIONS).pipe(
      map((carryPending): ITickDeltas => ({ rels, carryPending })),
    )),
  );
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  arrivals = validateArrivals(arrivals);
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE) {
    return runNaiveTick(seam, arrivals);
  }
  return runIncrementalTick(seam, arrivals);
}

